[package]
name = "glibc-bindings"
description = "Safe Rust wrappers over glibc's C API"
version.workspace = true
edition.workspace = true
license.workspace = true
rust-version.workspace = true
repository.workspace = true
publish.workspace = true

[features]
default = ["libc"]
libc = ["dep:libc-sys"]

[dependencies]
ffibox.workspace = true
libc-sys = { workspace = true, optional = true }

[dev-dependencies]
# The campaign's tests and gates regenerate the bindings, and check them against the
# committed ones; the crate's dependents build from the shipped bindings.
libc-sys = { workspace = true, features = ["bindgen"] }
trybuild.workspace = true

[lints]
workspace = true

[workspace]
resolver = "3"
members = [".", "libc-sys"]

[workspace.package]
version = "0.1.0"
edition = "2024"
rust-version = "1.100"
repository = "https://github.com/crustify-rs/glibc-bindings"
license = "LGPL-2.1-or-later"
publish = false

[workspace.dependencies]
bindgen = { version = "=0.73.2", features = ["experimental"] }
cc = "1.5"
ffibox = { git = "https://github.com/crustify-rs/ffibox", rev = "40621a29bffaede7a212c67eeadf803df6f1be29" }
trybuild = "1"
libc-sys = { version = "0.1.0", path = "libc-sys" }

[workspace.metadata.crustify]
nightly = "nightly-2026-10-08"

[workspace.lints.rust]
nonstandard_style = { level = "deny", priority = -1 }
unsafe_op_in_unsafe_fn = "deny"
missing_docs = "warn"
rust_2018_idioms = { level = "warn", priority = -1 }
unreachable_pub = "warn"
unused_qualifications = "warn"
unused_lifetimes = "warn"
let_underscore_drop = "warn"
trivial_casts = "warn"
trivial_numeric_casts = "warn"

[workspace.lints.clippy]
correctness = { level = "deny", priority = -1 }
all = { level = "warn", priority = -2 }
pedantic = { level = "warn", priority = -2 }
cargo = { level = "warn", priority = -2 }
undocumented_unsafe_blocks = "deny"
multiple_unsafe_ops_per_block = "deny"
missing_safety_doc = "deny"
unnecessary_safety_comment = "deny"
unnecessary_safety_doc = "deny"
mem_forget = "deny"
allow_attributes = "deny"
allow_attributes_without_reason = "deny"
module_inception = "allow"
module_name_repetitions = "allow"
multiple_crate_versions = "allow"

# ffibox is pinned by Git so that every crate in a graph resolves one copy of it;
# the patch points it at the local checkout while the campaign runs against it.
[patch."https://github.com/crustify-rs/ffibox"]
ffibox = { path = "/opt/venv/share/ffibox" }
//! Safe Rust wrappers over glibc's C API, one module per link unit.

#[cfg(feature = "libc")]
pub mod libc;
//! The `libc` link unit, laid out as glibc's C tree: one module per C directory.

/// Raw bindings to `libc`, generated from the host's headers.
pub use libc_sys as ffi;

pub mod csu;
pub mod libio;
pub mod stdio_common;
pub mod time;
//! `stdio-common/`: formatted output and the other stdio routines above `libio`.

pub mod fprintf;
//! `libio/`: glibc's stdio streams.

pub mod genops;
pub mod stdio;
//! `libio/stdio.c`: the standard streams `stdin`, `stdout` and `stderr`.
//! Safe wrappers over `csu/errno-loc.c`: the calling thread's `errno`, which C's
//! `errno` macro reaches through `__errno_location`.
//!
//! `errno` is thread-local, so reading and writing it races with nothing; every call made
//! between a read and a write may change it, as in C.

use core::ffi::c_int;

use crate::libc::ffi;

/// Wraps: `__errno_location`
///
/// The calling thread's `errno`: the error number the last failing call into C on this
/// thread left, as C's `errno` reads it.
#[must_use]
pub fn errno() -> c_int {
    // SAFETY: `__errno_location` returns the calling thread's `errno`, valid and aligned for
    // the thread's lifetime, which the read does not outlast.
    unsafe { location().read() }
}

/// Wraps: `__errno_location`
///
/// Sets the calling thread's `errno` to `value`, as C's `errno = value` does: before a call
/// whose failure only `errno` reports, or to restore the value a caller saw.
pub fn set_errno(value: c_int) {
    // SAFETY: as in `errno`: the calling thread's `errno`, valid for writes for the thread's
    // lifetime.
    unsafe { location().write(value) };
}

/// The calling thread's `errno`, valid for reads and writes for as long as the thread lives.
fn location() -> *mut c_int {
    // SAFETY: `__errno_location` takes no arguments and has no precondition.
    unsafe { ffi::__errno_location() }
}

#[cfg(test)]
mod unit_tests {
    use super::{errno, ffi, location, set_errno};

    #[test]
    fn set_errno_is_what_c_reads() {
        set_errno(ffi::ENOENT);
        // SAFETY: the calling thread's `errno`, valid for reads.
        assert_eq!(unsafe { location().read() }, ffi::ENOENT);
        assert_eq!(errno(), ffi::ENOENT);
        // SAFETY: as above, valid for writes.
        unsafe { location().write(ffi::EACCES) };
        assert_eq!(errno(), ffi::EACCES);
        set_errno(0);
        assert_eq!(errno(), 0);
    }
}
[package]
name = "libc-sys"
description = "Raw FFI bindings to glibc, generated from the host's headers"
links = "c"
build = "build.rs"
version.workspace = true
edition.workspace = true
license.workspace = true
rust-version.workspace = true
repository.workspace = true
publish.workspace = true

[lib]
# C doc comments carry C code blocks that are not Rust doctests.
doctest = false

[build-dependencies]
# Pinned exactly: the committed bindings are its output.
bindgen = { workspace = true, optional = true }
cc.workspace = true

[features]
# Regenerates the bindings from the host's headers, in place of the shipped ones.
bindgen = ["dep:bindgen"]
# `<kind> <regex>` per line, `kind` one of function, type, var; `#` comments.

# time/bits/types/struct_tm.h: the broken-down time, which libavutil's bprint.c and
# parseutils.c consume (crustify-rs/ffmpeg-bindings).
type tm

# libio/genops.c: the stream type, which libgit2's cli/opt.c and libavformat's dump.c hand
# a caller's stream as, and which fprintf and stderr name (crustify-rs/libgit2-bindings,
# crustify-rs/ffmpeg-bindings).
type _IO_FILE|FILE

# csu/errno-loc.c: the calling thread's errno, which libgit2's util/errors.c and its tests
# read and write (crustify-rs/libgit2-bindings).
function __errno_location

