//! Build script of a `-sys` crate, crustify's `specs/bindgen.md`'s, for libc: every
//! `-sys` crate of a campaign holds a copy of one script that differs only in the constants
//! below, but libc is the system's, so where the other copies locate a library, this one
//! takes the host's glibc in every mode, and builds and links nothing of it.
//!
//! - Shipped, by default: the committed `src/bindings.rs`, against the host's glibc, which must be
//!   the version the bindings were generated from.
//! - Regenerate, under the `bindgen` feature: bindings generated into `OUT_DIR` from the host's
//!   headers.
//! - Campaign, when `CRUSTIFY_BUILD_VARIANT` or `CRUSTIFY_BUILD_DIR` is set: the bindings are
//!   regenerated from the host's headers and checked against the committed ones, which
//!   `CRUSTIFY_BINDINGS_UPDATE=1` overwrites instead. libc has no variant: every variant of a
//!   campaign links the system's.

/// The link unit: its library.
const LIB: &str = "libc";
/// The version of the library the committed bindings were generated from.
const C_VERSION: &str = "2.39";
/// The link units this one depends on, whose `-sys` crates own their types.
#[cfg_attr(
    not(feature = "bindgen"),
    expect(dead_code, reason = "only regeneration reads it")
)]
const DEPS: &[&str] = &[];

use std::path::{Path, PathBuf};
use std::process::Command;
use std::{env, fs};

/// The headers and version of the library a build compiles and links against.
struct Library {
    include: Vec<PathBuf>,
    version: String,
}

fn main() {
    let manifest = PathBuf::from(env::var("CARGO_MANIFEST_DIR").unwrap());
    let input = manifest.join("bindgen");
    for f in [
        "wrapper.h",
        "allowlist.txt",
        "external.txt",
        "shims.h",
        "shims.c",
    ] {
        println!("cargo:rerun-if-changed={}", input.join(f).display());
    }
    for f in ["src/bindings.rs", "src/static_fns.c"] {
        println!("cargo:rerun-if-changed={}", manifest.join(f).display());
    }
    for v in [
        "CRUSTIFY_BUILD_VARIANT",
        "CRUSTIFY_BUILD_DIR",
        "CRUSTIFY_BINDINGS_UPDATE",
    ] {
        println!("cargo:rerun-if-env-changed={v}");
    }
    println!("cargo::rustc-check-cfg=cfg(crustify_regenerated)");
    // Dependents' build scripts read it as `DEP_<LINKS>_BINDGEN_DIR`.
    println!("cargo:bindgen_dir={}", input.display());

    let set = |v: &str| env::var_os(v).is_some_and(|s| !s.is_empty());
    let campaign = set("CRUSTIFY_BUILD_VARIANT") || set("CRUSTIFY_BUILD_DIR");
    let lib = host_library();
    let regenerate = cfg!(feature = "bindgen");
    if !regenerate && lib.version != C_VERSION {
        panic!(
            "{LIB} {} found, but the bindings were generated from {C_VERSION}: build on \
             glibc {C_VERSION}, or enable the `bindgen` feature to regenerate them",
            lib.version
        );
    }

    let mut static_fns = manifest.join("src/static_fns.c");
    if regenerate {
        let out = PathBuf::from(env::var("OUT_DIR").unwrap());
        let (bindings, fns) = generate(&input, &lib.include, &out);
        if campaign {
            check_or_update(&manifest.join("src/bindings.rs"), &bindings, &out);
            check_or_update(&static_fns, fns.as_deref().unwrap_or(""), &out);
            println!("cargo:rustc-env=C_VERSION={C_VERSION}");
        } else {
            fs::write(out.join("bindings.rs"), bindings).unwrap();
            static_fns = out.join("static_fns.c");
            fs::write(&static_fns, fns.unwrap_or_default()).unwrap();
            println!("cargo:rustc-cfg=crustify_regenerated");
            println!("cargo:rustc-env=C_VERSION={}", lib.version);
        }
    } else {
        println!("cargo:rustc-env=C_VERSION={C_VERSION}");
    }
    compile_wrappers(&input, &lib, &static_fns);
}

/// The host's glibc: its headers are the compiler's default ones, and every Rust binary
/// links it already.
fn host_library() -> Library {
    let out = Command::new("getconf")
        .arg("GNU_LIBC_VERSION")
        .output()
        .expect("getconf GNU_LIBC_VERSION");
    let text = String::from_utf8(out.stdout).expect("getconf prints UTF-8");
    let version = text
        .trim()
        .strip_prefix("glibc ")
        .unwrap_or_else(|| panic!("getconf GNU_LIBC_VERSION printed {text:?}, not glibc's"))
        .to_string();
    Library {
        include: Vec::new(),
        version,
    }
}

/// Compiles the macro shims and the wrappers of the `static inline` functions.
fn compile_wrappers(input: &Path, lib: &Library, static_fns: &Path) {
    let mut cc = cc::Build::new();
    cc.file(input.join("shims.c"))
        .includes(&lib.include)
        .include(input)
        .warnings(false);
    if fs::metadata(static_fns).is_ok_and(|m| m.len() > 0) {
        cc.file(static_fns);
    }
    cc.compile(&format!("crustify_{LIB}_wrappers"));
}

/// Fails the build when `path` does not hold `content`, unless asked to write it; the
/// content generated is left in `out` for comparison.
fn check_or_update(path: &Path, content: &str, out: &Path) {
    if fs::read_to_string(path).unwrap_or_default() == content {
        return;
    }
    if env::var_os("CRUSTIFY_BINDINGS_UPDATE").is_some() {
        if content.is_empty() {
            let _ = fs::remove_file(path);
        } else {
            fs::write(path, content).unwrap();
        }
        return;
    }
    let generated = out.join(path.file_name().unwrap());
    fs::write(&generated, content).unwrap();
    panic!(
        "{} does not match its bindgen input, which generates {}: rebuild with \
         CRUSTIFY_BINDINGS_UPDATE=1 and commit it",
        path.display(),
        generated.display()
    );
}

//! UB tests against the safe public API.
#![forbid(unsafe_code)]

mod errno_loc;
mod struct_tm_h;

/// Programs under `compile_fail/` must be rejected by the compiler.
#[test]
fn compile_fail() {
    let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/ub_safe/compile_fail");
    let any = std::fs::read_dir(&dir).is_ok_and(|d| {
        d.flatten()
            .any(|e| e.path().extension().is_some_and(|x| x == "rs"))
    });
    if any {
        trybuild::TestCases::new().compile_fail(dir.join("*.rs"));
    }
}
